}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #a8a9c4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ef233c;
    color: white;
    border-radius: 10px;
    padding: 2px 7px;
    font-size: 0.7rem;
    font-weight: 700;
}

/* Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #f8f9fa;
    min-width: 0;
}

.message-area-header {
    padding: 12px 20px;
    background: white;
    border-bottom: 1px solid #e0e0e0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #2b2d42;
}

.message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #6c757d;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.loading-indicator {
    text-align: center;
    color: #6c757d;
    padding: 8px;
    font-size: 0.85rem;
}

.message-bubble {
    padding: 8px 12px;
    border-radius: 6px;
    position: relative;
    transition: background 0.15s;
}

.message-bubble:hover {
    background: #e9ecef;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #2b2d42;
}

.message-time {
    font-size: 0.72rem;
    color: #868e96;
}

.message-content {
    font-size: 0.9rem;
    color: #343a40;
    line-height: 1.4;
